25	  .izgara { max-width: 1280px; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 28px 22px; justify-items: center; }
26	  .secenek { width: 100%; max-width: 330px; display: flex; flex-direction: column; gap: 12px; }
