    // Yazi girisi katmani
    yaziKatmani: { ...StyleSheet.absoluteFillObject, backgroundColor: 'rgba(0,0,0,0.6)', justifyContent: 'center', paddingHorizontal: bosluk.sayfa },
    yaziKutusu: { gap: bosluk.s },
    yaziGirdi: {
